    customerId: 'C-001',
    issueDate: '2025-01-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
